#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

const int MAX_SIZE = 250010;
long long fact[MAX_SIZE], invFact[MAX_SIZE];
long long dpTable[30][MAX_SIZE];
int bitCount[MAX_SIZE];
long long totalCount, maxLimit, modVal;

long long nCr(int n, int r) {
    return fact[n] * invFact[n - r] % modVal * invFact[r] % modVal;
}

void update(long long &x, long long y) {
    x += y;
    if (x >= modVal) x -= modVal;
}

int main() {
    cin >> totalCount >> maxLimit >> modVal;
    fact[0] = invFact[0] = 1;
    fact[1] = invFact[1] = 1;
    for (int i = 2; i <= totalCount; i++) {
        int q = modVal / i;
        int r = modVal - i * q;
        fact[i] = fact[i - 1] * i % modVal;
        invFact[i] = modVal - (long long)q * invFact[r] % modVal;
    }
    for (int i = 2; i <= totalCount; i++) {
        invFact[i] = invFact[i - 1] * invFact[i] % modVal;
    }
    long long result = 1;
    for (int i = 1; i <= totalCount; i++) result = result * maxLimit % modVal;
    for (int i = 1; i <= totalCount; i++) bitCount[i] = bitCount[i >> 1] + (i & 1);
    if (totalCount % 2 == 1) {
        cout << result << endl;
        return 0;
    }
    dpTable[0][0] = 1;
    int maxBits = min((long long)bitCount[totalCount], maxLimit);
    for (int i = 0; i < maxBits; i++) {
        for (int j = 0; j < totalCount; j++) {
            if (dpTable[i][j] == 0) continue;
            int mask = totalCount ^ j;
            for (int k = mask, r; k > j; k = (k - 1) & mask) {
                r = k | j;
                update(dpTable[i + 1][r], dpTable[i][j] * invFact[k]);
            }
        }
    }
    for (int i = 1; i <= maxLimit; i++) {
        result -= dpTable[i][totalCount] * fact[maxLimit] % modVal * invFact[maxLimit - i] % modVal * fact[totalCount] % modVal;
    }
    result = (modVal + result % modVal) % modVal;
    cout << result << endl;
    return 0;
}
